import React from 'react';
import styled from 'styled-components';
import { devices } from '../styles/breakpoints';
import Banner from '../components/common/Banner';
import ProductPromotion from '../components/common/ProductPromotion';
import VideoPlayer from '../components/common/VideoPlayer';
import TestimonialGallery from '../components/common/TestimonialGallery';
import { 
  bpMonitorProducts, 
  bpMonitorTestimonials,
  bpMonitorsBannerItems,
  bpMonitorPromotionProducts
} from '../data/products';

const PageWrapper = styled.div`
  width: 100%;
  padding-top: 60px;

  ${devices.tablet} {
    padding-top: 80px;
  }
`;

// BpMonitors页面专用的ProductPromotion样式包装器
const BpMonitorProductPromotion = styled(ProductPromotion)`
  .promotion-grid {
    max-width: auto !important;
    ${devices.tablet} {
      max-width: 1567px !important;
    }
    .product-card {
      padding: 30px !important;
      ${devices.tablet} {
        padding: 65px 140px !important;
      }
    }
    .product-image {
      width: auto !important;
      background: none !important;
    }
  }
    .shop-button {
      margin-left: 30px !important;
      ${devices.tablet} {
        margin-left: 140px !important;
      }
    }
`;

const SecondPromotionSection = styled.section`
  padding: 60px 20px;
  background: #F5F5F5;

  ${devices.tablet} {
    padding: 80px 144px;
  }

  h2 {
    font-size: 14px;
    margin-bottom: 8px;
    color: #000;
    font-weight: 400;
    text-align: left;

    ${devices.tablet} {
      font-size: 40px;
      margin-bottom: 16px;
    }
  }

  .subtitle {
    font-size: 20px;
    color: #000;
    margin-bottom: 40px;
    font-weight: 700;
    text-align: left;

    ${devices.tablet} {
      font-size: 40px;
      margin-bottom: 60px;
    }
  }
`;

const MediaGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;

  ${devices.tablet} {
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    max-width: none;
  }
`;

const MediaItem = styled.div`
  position: relative;
  overflow: hidden;
  height: auto;

  ${devices.tablet} {
    height: 400px;
  }

  &.large {
    ${devices.tablet} {
      grid-row: span 2;
      height: 670px;
    }
  }

  &.small-item {
    ${devices.tablet} {
      height: 325px;
    }
  }

  img, video {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
  

  .play-button {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80px;
    height: 80px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    border: 2px solid #fff;

    &:hover {
      background: white;
      transform: translate(-50%, -50%) scale(1.1);
    }

    &::after {
      content: '';
      width: 0;
      height: 0;
      border-left: 16px solid #333;
      border-top: 10px solid transparent;
      border-bottom: 10px solid transparent;
      margin-left: 3px;
    }
  }

  .content-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(0,0,0,0.3) 0%, rgba(0,0,0,0.1) 100%);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 30px;
    color: white;
  }

  .top-text {
    text-align: left;
    
    .badge {
      background: rgba(255, 255, 255, 0.2);
      backdrop-filter: blur(10px);
      padding: 6px 12px;
      border-radius: 20px;
      font-size: 12px;
      font-weight: 500;
      display: inline-block;
      margin-bottom: 16px;
    }
    
    h3 {
      font-size: 28px;
      font-weight: 700;
      margin: 0 0 8px 0;
      line-height: 1.2;
    }

    p {
      font-size: 16px;
      margin: 0;
      opacity: 0.9;
    }
  }

  .bottom-text {
    text-align: left;
    
    .specs {
      font-size: 14px;
      opacity: 0.8;
      margin-bottom: 4px;
    }
    
    .main-text {
      font-size: 18px;
      font-weight: 600;
    }
  }
`;

const BPMonitorTestimonialGallery = styled(TestimonialGallery)`
  .testimonial-header {
    margin-left: 0 !important;
    ${devices.tablet} {
      margin-left: 144px !important;
    }
  }
`;

const VideoSection = styled.section`
  position: relative;
  width: 100%;
  height: 300px;
  overflow: hidden;

  ${devices.tablet} {
    height: calc(100vw / 2);
  }
`;

const BpMonitors: React.FC = () => {

  return (
    <PageWrapper>
      <Banner
        items={bpMonitorsBannerItems}
      />

      <BpMonitorProductPromotion
        className="bp-monitor-promotion"
        products={bpMonitorPromotionProducts}
        styleConfig={{
          cardBackground: 'none',
          imageHeight: '485px',
        }}
        onProductClick={(product) => console.log('BP Monitor product clicked:', product)}
        onShopNowClick={(product) => console.log('Shop now clicked:', product)}
      />

      <SecondPromotionSection>
        <h2>Benefit from a 10% discount on your first order by registering</h2>
        <div className="subtitle">TODAY'S PROMOTIONS</div>
        <MediaGrid>
          <MediaItem className="large">
            <img src="/images/BpMonitors/bp_product_3.jpg" alt="" />
          </MediaItem>
          <MediaItem className="small-item">
            <img src="/images/BpMonitors/bp_product_4.jpg" alt="Clear Visibility Display" />
          </MediaItem>
          <MediaItem className="small-item">
            <img src="/images/BpMonitors/bp_product_5.jpg" alt="Patented Large Cuff" />
          </MediaItem>
        </MediaGrid>
      </SecondPromotionSection>

      <BPMonitorTestimonialGallery
        title="What Our Customers Say"
        subtitle="Real experiences from our users who trust our BP monitors"
        testimonials={bpMonitorTestimonials}
        showControls={true}
        onTestimonialClick={(testimonial) => console.log('Testimonial clicked:', testimonial)}
      />

      <VideoSection>
        <VideoPlayer
          src="/images/BpMonitors/bp_product_video.mp4"
          poster="/images/BpMonitors/bp_product_video_bg.png"
          hideMobileButton={true}
        />
      </VideoSection>
    </PageWrapper>
  );
};

export default BpMonitors; 