import React from 'react';
import styled from 'styled-components';
import { devices } from '../styles/breakpoints';
import Banner from '../components/common/Banner';
import { aboutBannerItems } from '../data/products';

const PageWrapper = styled.div`
  width: 100%;
  padding-top: 60px;
  background: #F4F4F4;

  ${devices.tablet} {
    padding-top: 80px;
  }
`;

const About: React.FC = () => {

  return (
    <PageWrapper>
      <Banner
        items={aboutBannerItems}
        autoplay={false}
        showArrows={false}
      />
      <img src="/images/About/about_content_1.jpg" alt="About Ovutek" />
      <img src="/images/About/about_content_2.jpg" alt="About Ovutek" />
      <img src="/images/About/about_content_3.jpg" alt="About Ovutek" />
    </PageWrapper>
  );
};

export default About; 